					value = scope:quantity
					divide = {
						value = scope:target_country.fixed_income
						min = 1
					}
					multiply = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_TARGET_SHARE_MULT
					min = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_SHARE_MIN
					max = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_SHARE_MAX
				}

				add = {
					desc = "INFAMY_MONEY_TRANSFER_SELF_SHARE"
					value = scope:quantity

					every_scope_treaty = {
						limit = {
							any_scope_article = {
								has_type = money_transfer
								target_country = root
							}
						}
						every_scope_article = {
							limit = {
								has_type = money_transfer
								target_country = root
							}
							add = input_quantity
						}
					}

					divide = {
						value = tax_income
						min = 1
					}
					multiply = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_SELF_SHARE_MULT
					min = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_SHARE_MIN
					max = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_SHARE_MAX
				}
			}

			if = {
				limit = {
					any_diplomatic_play = {
						initiator = scope:target_country
						target = root
					}
				}
				multiply = {
					desc = "INFAMY_TARGET_COUNTRY_DEDUCTION_FACTOR"
					value = define:NDiplomacy|WAR_GOAL_INFAMY_MONEY_TRANSFER_DEFENDER_MULT
				}
			}
		}
	}
